"""Every figure quoted in the worked example on each tool page, checked against what the page itself shows
(and, for the astronomy, against astropy)."""
import sys, datetime as dt
from common import *
T = Tally('worked examples printed on the pages')
def page(slug, case, tag='ex'): return drive(slug, [case], tag)[0]
def has(label, text, *parts):
    for p in parts: T.check(label, p in (text or ''), 'want %r in %r' % (p, text))

